'use strict';
function focusKey(){return storageKey()+'-focus'}
function loadFocus(){const empty={tiles:0,sessions:0,session:null,lastMessage:''};try{const d=JSON.parse(localStorage.getItem(focusKey())||'null');if(!d||!Number.isInteger(d.tiles)||d.tiles<0||!Number.isInteger(d.sessions)||d.sessions<0)return empty;if(d.session&&(![5,15,25].includes(d.session.minutes)||!Number.isFinite(d.session.remainingMs)||d.session.remainingMs<0||d.session.remainingMs>d.session.minutes*60000||typeof d.session.paused!=='boolean'||(!d.session.paused&&(!Number.isFinite(d.session.endAt)||d.session.endAt<=0))))return empty;return d}catch(err){return empty}}
let focusData=loadFocus();
function saveFocus(){try{localStorage.setItem(focusKey(),JSON.stringify(focusData))}catch(err){toast('Focus rewards could not save in this browser.')}}
function focusRemaining(){const s=focusData.session;return s?Math.max(0,s.paused?s.remainingMs:s.endAt-Date.now()):+$('#focus-length').value*60000}
function finishFocus(){const s=focusData.session;if(!s)return;focusData.tiles+=s.minutes;focusData.sessions++;focusData.lastMessage=`Nice work, ${s.actor}! ${s.minutes} LED tiles earned. ✦`;focusData.session=null;saveFocus()}
function renderFocus(){const s=focusData.session;if(s&&!s.paused&&focusRemaining()<=0)finishFocus();const current=focusData.session,remaining=focusRemaining(),seconds=Math.ceil(remaining/1000),progress=current?1-remaining/(current.minutes*60000):0;$('#focus-clock').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');$('#focus-wall').innerHTML=Array.from({length:32},(_,i)=>`<span class="led-tile ${i<Math.floor(progress*32)?'lit '+(current.actor||actor).toLowerCase():''}"></span>`).join('');$('#focus-message').textContent=current?(current.paused?'Paused · resume when you’re ready.':`Focusing ${current.title?'on '+current.title:'on one good thing'}.`):(focusData.lastMessage||'One task. A little space to focus.');$('#focus-start').textContent=current?(current.paused?'Resume focus':'Pause'):'Start focus';$('#focus-stop').disabled=!current;$('#focus-task').disabled=!!current;$('#focus-length').disabled=!!current;$('#focus-earned').textContent=focusData.tiles+' tiles earned';$('#focus-sessions').textContent=focusData.sessions+' sessions completed';$('#focus-button').innerHTML=current?`✦ Focus · ${$('#focus-clock').textContent}<span>${current.paused?'Ⅱ':'●'}</span>`:'✦ Focus arcade <span>→</span>';}
function openFocus(){const selected=$('#focus-task').value;$('#focus-task').innerHTML='<option value="">A little open focus time</option>'+tasks.filter(t=>t.status!=='Done').map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('');if(tasks.some(t=>t.id===selected))$('#focus-task').value=selected;renderFocus();$('#focus-dialog').showModal()}
$('#focus-button').onclick=openFocus;$('#close-focus').onclick=()=>$('#focus-dialog').close();$('#focus-length').onchange=renderFocus;
$('#focus-start').onclick=()=>{const s=focusData.session;if(s){if(s.paused){s.paused=false;s.endAt=Date.now()+s.remainingMs}else{s.remainingMs=focusRemaining();s.paused=true}}else{const minutes=+$('#focus-length').value,task=tasks.find(t=>t.id===$('#focus-task').value);focusData.session={minutes,remainingMs:minutes*60000,endAt:Date.now()+minutes*60000,paused:false,actor,title:task?.title||''};focusData.lastMessage=''}saveFocus();renderFocus()};
$('#focus-stop').onclick=()=>{focusData.session=null;focusData.lastMessage='A fresh start whenever you need it.';saveFocus();renderFocus()};
setInterval(renderFocus,1000);renderFocus();
